import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`document-verification`,heroTitle:`Verify your documents in minutes—with Final Pass.`,heroSubtitle:`Perplexity Computer reviews uploaded documents, checks claims against supporting evidence, SEC filings, trusted publications and returns a verification report with flagged risks.`,hasInputUrl:!1,hasInputFile:!0,inputFileCta:`Verify my document`,inputFileAccept:`.pdf,.doc,.docx`,inputFilePrefill:`Review the uploaded document and verify its claims, figures, dates, entities, and supporting evidence. 1) Extract the key claims, obligations, numbers, parties, and source references. 2) Check for inconsistencies, unsupported statements, missing attachments, stale dates, and internal contradictions. 3) Mark each issue by severity and explain what evidence is needed to resolve it. 4) Create a verification checklist and a source request list. 5) Deliver a concise due diligence report with confirmed items, open questions, and recommended next steps.`,heroOverlaySteps:[`Extracting claims, figures, dates, parties, and source references`,`Checking for inconsistencies, missing evidence, and stale details`,`Prioritizing issues by severity and evidence needed`,`Verification report and source request list ready to review`],generatingSteps:[`Reading the uploaded document to identify claims, figures, parties, and references`,`Designing an agent to verify internal consistency and supporting evidence`,`Configuring severity labels, evidence gaps, and source request tracking`,`Setting up the final due diligence report and verification checklist`],featureSectionTitle:`From uploaded document to verified findings`,featureCardTitles:[`Connects to your diligence materials`,`Outputs you can review`],featureCardDescriptions:[`Computer breaks verification into claim extraction, evidence checking, contradiction detection, and report writing.`,`PDFs, contracts, data rooms, Docs, Sheets, Drive, Notion, and Slack can feed one organized diligence workflow.`,`Confirmed items. Open questions. Evidence gaps. Severity labels. Source request list. Computer delivers a report ready for review.`],capabilitySectionTitle:`Your diligence analyst, on autopilot`,capabilitySectionSubtitle:`Upload a document and get back a structured verification report.`,capabilityCards:[{title:`Claim Extraction`,description:`Computer can identify key claims, figures, dates, obligations, parties, and source references from uploaded documents.`},{title:`Evidence Check`,description:`Computer can compare claims against cited support and flag missing evidence, stale references, or unclear source trails.`},{title:`Risk Prioritization`,description:`Computer can group issues by severity, business impact, and the evidence needed to resolve each open item.`},{title:`Connect Your Tools`,description:`Computer can organize diligence files across Google Drive, Docs, Sheets, Notion, and Slack.`},{title:`Remember Your Checklist`,description:`Computer can remember your verification standards, diligence templates, and recurring source request formats.`},{title:`Follow-Up Tracking`,description:`Computer can monitor open evidence requests and remind stakeholders when missing documents or answers are due.`}]});export{t as default};
